#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25
# Night programme (Fatih away): wait for GO (or 22:00) and an idle host -> split -> (1c) container-shim cost campaign on
# Autoware fishwait28 (baseline / lttng without shim / lttng with shim, x3 interleaved) -> (TASK 4) every Isaac family on
# its -fishdeterministic image (lttng x1) -> post_run_pipeline for every new session -> host back to off.
# Usage: bash scripts/night_queue_20261025.sh   (touch $LD/GO to start early; log: $LD/queue.log)
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/queue.log"; }
pipelines_since() {  # $1 = marker (last session dir before the phase); run the pipeline for every newer session
  for d in $(ls -d "$HOME"/fish_traces/fish_2* | sort | awk -v b="$1" '$0 > b'); do
    S=$(basename "$d"); [ -f "$LD/pipelines_done.txt" ] && grep -q "^$S$" "$LD/pipelines_done.txt" && continue
    log "pipeline $S"; bash scripts/post_run_pipeline.sh "$S" "$HOME/fish_traces/analysis_$S" > "$LD/pipeline_$S.log" 2>&1 || log "pipeline $S FAILED"
    echo "$S" >> "$LD/pipelines_done.txt"
  done
}
while [ ! -f "$LD/GO" ] && [ "$(date +%H)" -lt 22 ]; do sleep 60; done
while docker ps --no-trunc --format '{{.Command}}' | grep -q "source_flow.py\|colcon build"; do sleep 60; done
log "start: host idle"
sudo -n /usr/local/sbin/fish-host-perf-mode split >> "$LD/queue.log" 2>&1 || { log "ABORT: split failed"; exit 1; }
IMG=autoware-dev-trt-a1000-fishwait28:latest
EV=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids
M0=$(ls -d "$HOME"/fish_traces/fish_2* | sort | tail -1)
: > "$LD/plan_1c.txt"
for i in 1 2 3; do
  echo "base$i IMG=$IMG MODES=baseline" >> "$LD/plan_1c.txt"
  echo "noshim$i IMG=$IMG MODES=lttng FISH_CONTAINER_SHIM=0 FISH_EXTRA_EVENTS=$EV" >> "$LD/plan_1c.txt"
  echo "shim$i IMG=$IMG MODES=lttng FISH_CONTAINER_SHIM=1 FISH_EXTRA_EVENTS=$EV" >> "$LD/plan_1c.txt"
done
log "1c: 9 Autoware runs (split, cooldown + desk gates)"
bash scripts/night_runs.sh "$LD" < "$LD/plan_1c.txt" >> "$LD/queue.log" 2>&1
pipelines_since "$M0"
M1=$(ls -d "$HOME"/fish_traces/fish_2* | sort | tail -1)
for F in apriltag bi3d bi3d_freespace detectnet dnn_image_encoder dope ess image_proc nitros_bridge nvblox rtdetr segformer stereo_image_proc tensor_rt triton unet visual_slam; do
  log "task4 $F"
  IMG_OVERRIDE=fish-r2b-$F-fishdeterministic:latest REPS=1 MODES=lttng DEST_BASE="$LD/task4" SMOKE_TIMEOUT=1200 FISH_EXTRA_EVENTS=$EV \
    bash scripts/overhead_sweep_v8.sh "$F" > "$LD/task4_$F.log" 2>&1 || log "task4 $F rc=$?"
  pipelines_since "$M1"
done
sudo -n /usr/local/sbin/fish-host-perf-mode off >> "$LD/queue.log" 2>&1
log "QUEUE DONE"
